  "• Autenticarte y mantener tu sesión.": { en: "• Authenticate you and keep your session.", fr: "• Vous authentifier et maintenir votre session.", pt: "• Autenticar você e manter sua sessão." },
  "• Procesar tus reservas y notificarte cuando el partner las confirme.": { en: "• Process your bookings and notify you when the partner confirms them.", fr: "• Traiter vos réservations et vous notifier lorsque le partenaire les confirme.", pt: "• Processar suas reservas e notificar quando o parceiro confirmar." },
  "• Personalizar recomendaciones del agente IA según tu historial y favoritos.": { en: "• Personalize AI agent recommendations based on your history and favorites.", fr: "• Personnaliser les recommandations de l'agent IA selon votre historique et favoris.", pt: "• Personalizar recomendações do agente de IA conforme seu histórico e favoritos." },
  "• Cumplir obligaciones legales y prevenir fraude.": { en: "• Meet legal obligations and prevent fraud.", fr: "• Respecter les obligations légales et prévenir la fraude.", pt: "• Cumprir obrigações legais e prevenir fraude." },
